def splitBranchIndex {n : ℕ} (e : (Fin n → Bool) → ℕ → ℕ) (p : ℕ → ℕ)
    (a : Fin (n + 1) → Bool) (k : ℕ) : ℕ :=
  e (binaryPrefix a) (2 * p k + if binaryLast a then 1 else 0)

